```ts
export interface DebouncedFunction<A extends unknown[]> {
  (...args: A): void;
  /** Cancels the pending invocation, if any. The function is not called. */
  cancel(): void;
}

export function debounce<A extends unknown[]>(
  fn: (...args: A) => unknown,
  waitMs: number,
): DebouncedFunction<A> {
  if (!Number.isFinite(waitMs) || waitMs < 0) {
    throw new RangeError(
      `debounce: waitMs must be a non-negative finite number, got ${waitMs}`,
    );
  }

  let timer: ReturnType<typeof setTimeout> | undefined;

  const debounced = (...args: A): void => {
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = undefined;
      fn(...args);
    }, waitMs);
  };

  debounced.cancel = (): void => {
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
  };

  return debounced;
}
```

Usage:

```ts
import { debounce } from "./utils/debounce";

const save = debounce((id: string, draft: string) => api.save(id, draft), 300);
save("doc-1", "hello"); // runs once, 300ms after the last call
save.cancel();          // drops the pending call
```

- **Generics:** the returned function keeps the wrapped function's parameter types, so `save("doc-1", 42)` is a compile error.
- **Trailing edge only:** `fn` runs once, after calls stop for `waitMs`. The wrapper returns `void`, because the result arrives later.
- **Cancel:** `cancel()` clears the pending timer, so `fn` is not called. It is safe to call when nothing is pending.

